function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Number.isInteger(k) || k < 1 || k > 1e15) return 'k is between 1 and 10^15.';
  return null;
}

