function permute(n, k) {
  const fact = [1];
  for (let i = 1; i <= n; i++) {
    fact.push(Math.min(fact[i - 1] * i, Number.MAX_SAFE_INTEGER));
  }
  let odds = Math.ceil(n / 2);
  let evens = Math.floor(n / 2);
  const total = (odds === evens ? 2 : 1) * fact[odds] * fact[evens];
  if (k > total) {
    return [];
  }
  const used = new Array(n + 1).fill(false);
  const result = [];
  for (let pos = 0; pos < n; pos++) {
    for (let x = 1; x <= n; x++) {
      if (used[x]) continue;
      const odd = x % 2 === 1;
      if (pos === 0 && odds > evens && !odd) continue;
      if (pos > 0 && odd === (result[pos - 1] % 2 === 1)) continue;
      const ways = odd ? fact[odds - 1] * fact[evens] : fact[odds] * fact[evens - 1];
      if (k > ways) {
        k -= ways;
        continue;
      }
      used[x] = true;
      result.push(x);
      if (odd) odds--;
      else evens--;
      break;
    }
  }
  return result;
}

brute:
function permute(n, k) {
  // Enumerate alternating arrangements in lexicographic order with backtracking and stop at the k-th.
  const path = [];
  const used = new Array(n + 1).fill(false);
  let seen = 0;
  let answer = [];
  const search = () => {
    if (path.length === n) {
      seen++;
      if (seen === k) answer = path.slice();
      return seen === k;
    }
    for (let x = 1; x <= n; x++) {
      if (used[x] || (path.length > 0 && path[path.length - 1] % 2 === x % 2)) continue;
      used[x] = true;
      path.push(x);
      if (search()) return true;
      path.pop();
      used[x] = false;
    }
    return false;
  };
  search();
  return answer;
}

