function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  // How many alternating arrangements 1..n has; exact for the n <= 21 used with it here.
  const count = n => {
    const fact = [1];
    for (let i = 1; i <= n; i++) fact.push(fact[i - 1] * i);
    const odds = Math.ceil(n / 2), evens = Math.floor(n / 2);
    return (odds === evens ? 2 : 1) * fact[odds] * fact[evens];
  };
  if (size === 'large') {
    if (rand() < 0.6) return [int(80, 100), int(1, 1e15)];
    const n = int(15, 21), total = count(n), pick = rand();
    return [n, pick < 0.35 ? total : pick < 0.5 ? total + 1 : int(1, total)];
  }
  const n = int(1, 10), total = count(n), pick = rand();
  const k = pick < 0.15 ? 1 : pick < 0.3 ? total : pick < 0.4 ? total + int(1, 3) : pick < 0.45 ? int(1, 1e15) : int(1, total);
  return [n, k];
}
